arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo "exit $?"
sed -i 's|(\($1 \* 90\) + 99) / 100|\1 / 100|' bin/price bin/quote lib/invoice.sh
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
grep -rn "90" bin/price bin/quote lib/invoice.sh
mkdir -p notes; cat > notes/PRC-412.md <<'EOF'
# PRC-412
Cause: f02b252 "tidy up rounding" changed `$1*90/100` to `($1*90+99)/100` (round up) in bin/price, bin/quote, lib/invoice.sh.
Fix: restore round-down in all three; tests added for 999 in each.
EOF
bash scripts/verify.sh; echo "exit $?"

